const missions = msg.missions || [];
const messages = [];

for (const m of missions) {
    messages.push({
        url: 'https://external.dronesense.com/v1/drones/with-sensors',
        headers: { 'x-api-key': m.key },
        missionLabel: m.name
    });
}

return [messages];

const items = msg.payload || [];
if (!Array.isArray(items)) return [null];

const missionLabel = msg.missionLabel || '';
const serverAddress = env.get('SERVER_ADDRESS') || 'localhost';
const staleSeconds = parseInt(env.get('DRONESENSE_STALE_SECONDS') || '10', 10);

function xmlEscape(s) {
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
}

function pickCotType(item) {
    if (item.isDrone) return 'a-f-A-M-H-Q';
    const hasVideo = (item.sensors || []).some(s => s.rtsp_url);
    return hasVideo ? 'a-f-G-E-S' : 'a-f-G-U-C';
}

const cotMsgs = [];
const nowMs = Date.now();
const time = new Date(nowMs).toISOString();
const stale = new Date(nowMs + staleSeconds * 1000).toISOString();

// Desired MediaMTX proxy paths — shared across all missions; the Reconcile
// MediaMTX node snapshots this on its own timer.
const desired = flow.get('dsDesired') || {};

for (const item of items) {
    if (item.latitude == null || item.longitude == null) continue;

    const cotType = pickCotType(item);
    const platformUid = `ds-${item.id}`;
    const callsignBase = item.callSign || item.model || item.id;
    const displayCallsign = missionLabel ? `${missionLabel} // ${callsignBase}` : callsignBase;
    const model = item.model || 'Unknown';
    const hae = item.altitudeMsl != null ? item.altitudeMsl : 0;
    const course = item.heading != null ? item.heading : 0;
    const speed = (item.speed != null && item.speed >= 0) ? item.speed : 0;

    const hasSpi = item.spoiLat != null && item.spoiLng != null;
    const spiShort = hasSpi ? `${callsignBase}.SPI1` : '';

    const activeSensors = (item.sensors || []).filter(s => s.rtsp_url);
    let videoXml = '<__video/>';
    if (activeSensors.length > 0) {
        videoXml = '';
        for (const sensor of activeSensors) {
            const proxyPath = `ds/${sensor.id}`;
            // Record desired proxy source; Reconcile keeps MediaMTX in sync.
            desired[proxyPath] = { source: sensor.rtsp_url, ts: nowMs };

            const proxyUrl = `rtsp://${serverAddress}:8554/${proxyPath}?tcp`;
            const feedUid = `ds-video-${sensor.id}`;
            const sensorName = sensor.name || callsignBase;
            const alias = missionLabel ? `${missionLabel} // ${sensorName}` : sensorName;

            videoXml +=
                `<__video sensor="${xmlEscape(displayCallsign)}" spi="${xmlEscape(spiShort)}" url="${xmlEscape(proxyUrl)}">` +
                `<ConnectionEntry networkTimeout="12000" uid="${xmlEscape(feedUid)}" ` +
                `path="/${xmlEscape(proxyPath)}" protocol="rtsp" bufferTime="-1" ` +
                `address="${xmlEscape(serverAddress)}" port="8554" roverPort="-1" rtspReliable="0" ` +
                `alias="${xmlEscape(alias)}"/>` +
                `</__video>`;
        }
    }

    const remarkLines = [missionLabel ? `${model} — ${missionLabel}` : model];
    for (const sensor of (item.sensors || [])) {
        if (sensor.rtsp_url) remarkLines.push(`RTSP: ${sensor.rtsp_url}`);
        if (sensor.video_url) remarkLines.push(`Web: ${sensor.video_url}`);
    }
    const remarks = remarkLines.join('\n');

    const platformCot =
        `<?xml version="1.0" encoding="UTF-8"?>` +
        `<event version="2.0" uid="${xmlEscape(platformUid)}" type="${cotType}" how="m-g" ` +
        `time="${time}" start="${time}" stale="${stale}">` +
        `<point lat="${item.latitude}" lon="${item.longitude}" hae="${hae}" ce="9999999.0" le="9999999.0"/>` +
        `<detail>` +
        `<contact callsign="${xmlEscape(displayCallsign)}"/>` +
        `<track course="${course}" slope="0.0" speed="${speed}"/>` +
        `<precisionlocation altsrc="GPS"/>` +
        `<remarks>${xmlEscape(remarks)}</remarks>` +
        videoXml +
        `</detail>` +
        `</event>`;
    cotMsgs.push({ payload: platformCot });

    if (hasSpi) {
        const spiUid = `${callsignBase}.${platformUid}.SPI1`;
        const spiCot =
            `<?xml version="1.0" encoding="UTF-8"?>` +
            `<event version="2.0" uid="${xmlEscape(spiUid)}" type="b-m-p-s-p-i" how="m-g" ` +
            `time="${time}" start="${time}" stale="${stale}">` +
            `<point lat="${item.spoiLat}" lon="${item.spoiLng}" hae="0.0" ce="9999999.0" le="9999999.0"/>` +
            `<detail>` +
            `<contact callsign="${xmlEscape(spiShort)}"/>` +
            `<link uid="${xmlEscape(platformUid)}" type="${cotType}" relation="p-p"/>` +
            `<precisionlocation altsrc="GPS"/>` +
            `</detail>` +
            `</event>`;
        cotMsgs.push({ payload: spiCot });
    }
}

flow.set('dsDesired', desired);
return [cotMsgs];

// Reconcile MediaMTX ds/* proxy paths against the desired set that Build CoT
// accumulates in flow context. Independent timer so it sees all missions.
const FRESH_MS = 15000;   // a sensor unseen this long is considered offline

// --- synchronous prologue: snapshot + prune desired atomically ---
const now = Date.now();
const raw = flow.get('dsDesired') || {};
const desired = {};   // name -> source
const pruned = {};
for (const [name, e] of Object.entries(raw)) {
    if (now - e.ts < FRESH_MS) { desired[name] = e.source; pruned[name] = e; }
}
flow.set('dsDesired', pruned);

const fpCache = flow.get('_dsFingerprintCache') || {};

function httpJson(method, path, bodyObj) {
    return new Promise((resolve) => {
        const data = bodyObj ? JSON.stringify(bodyObj) : null;
        const req = http.request({
            host: 'mediamtx', port: 9997, method, path,
            headers: data
                ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) }
                : {}
        }, (res) => {
            let buf = '';
            res.on('data', (c) => { buf += c; });
            res.on('end', () => resolve({ status: res.statusCode, body: buf }));
        });
        req.on('error', (e) => resolve({ status: 0, error: e.message }));
        req.setTimeout(5000, () => { req.destroy(); resolve({ status: 0, error: 'timeout' }); });
        if (data) req.write(data);
        req.end();
    });
}

function getFingerprint(host, port) {
    return new Promise((resolve) => {
        const sock = tls.connect({ host, port, rejectUnauthorized: false }, () => {
            const cert = sock.getPeerCertificate(true);
            const fp = crypto.createHash('sha256').update(cert.raw).digest('hex');
            sock.destroy();
            resolve(fp);
        });
        sock.on('error', () => resolve(''));
        sock.setTimeout(5000, () => { sock.destroy(); resolve(''); });
    });
}

async function ensureFingerprint(source) {
    try {
        const u = new URL(source);
        const hp = `${u.hostname}:${u.port}`;
        if (fpCache[hp]) return fpCache[hp];
        const fp = await getFingerprint(u.hostname, parseInt(u.port, 10));
        if (fp) { fpCache[hp] = fp; node.log(`ds: cached TLS fingerprint for ${hp}`); }
        return fp;
    } catch (e) { return ''; }
}

async function listCurrent() {
    const r = await httpJson('GET', '/v3/config/paths/list?itemsPerPage=1000');
    if (r.status !== 200) throw new Error(`list HTTP ${r.status}${r.error ? ' ' + r.error : ''}`);
    const data = JSON.parse(r.body);
    const cur = {};
    for (const p of (data.items || [])) {
        if (p.name && p.name.startsWith('ds/')) cur[p.name] = p.source;
    }
    return cur;
}

return (async () => {
    let current;
    try {
        current = await listCurrent();
    } catch (e) {
        node.warn(`ds: cannot read MediaMTX paths: ${e.message}`);
        return;
    }

    // add new / replace rotated; skip unchanged (no churn on a live recording)
    for (const [name, source] of Object.entries(desired)) {
        if (current[name] === source) continue;
        const verb = (current[name] === undefined) ? 'add' : 'replace';
        const fp = await ensureFingerprint(source);
        if (!fp) { node.warn(`ds: skip ${name} (no fingerprint yet)`); continue; }
        const r = await httpJson('POST', `/v3/config/paths/${verb}/${name}`,
            { source, sourceFingerprint: fp, sourceOnDemand: false });
        if (r.status >= 200 && r.status < 300) {
            node.log(`ds: ${verb === 'add' ? 'registered' : 'replaced (endpoint rotated)'} ${name}`);
        } else {
            node.warn(`ds: ${verb} ${name} -> HTTP ${r.status}${r.error ? ' ' + r.error : ''}`);
        }
    }

    // delete offline sensors / orphaned paths (incl. pre-existing stale ones)
    for (const name of Object.keys(current)) {
        if (!(name in desired)) {
            const r = await httpJson('DELETE', `/v3/config/paths/delete/${name}`);
            if (r.status >= 200 && r.status < 300) node.log(`ds: deleted ${name} (offline)`);
        }
    }

    // prune fingerprint cache to endpoints still referenced by desired sources
    const wantedHosts = new Set();
    for (const source of Object.values(desired)) {
        try { const u = new URL(source); wantedHosts.add(`${u.hostname}:${u.port}`); } catch (e) {}
    }
    for (const hp of Object.keys(fpCache)) {
        if (!wantedHosts.has(hp)) delete fpCache[hp];
    }
    flow.set('_dsFingerprintCache', fpCache);
})();
